function renderYksNedir(el) {
  const kart = (icon, baslik, alt, tab) => `
    <div onclick="switchToTab('${tab}')" style="cursor:pointer;display:flex;align-items:center;gap:14px;background:rgba(255,253,247,0.85);border:1px solid rgba(180,140,60,0.3);border-radius:16px;padding:16px;margin-bottom:12px;box-shadow:0 3px 10px rgba(120,90,30,0.1);transition:transform 0.15s ease;">
      <div style="flex-shrink:0;width:52px;height:52px;border-radius:14px;background:linear-gradient(135deg,#8a6a2f,#d4af5a 60%,#b8903f);display:flex;align-items:center;justify-content:center;font-size:1.6rem;box-shadow:0 3px 8px rgba(120,90,30,0.3);">${icon}</div>
      <div style="flex:1;">
        <div style="font-weight:800;font-size:0.95rem;color:#3a2a15;">${baslik}</div>
        <div style="font-size:0.75rem;color:#6b5636;margin-top:2px;">${alt}</div>
      </div>
      <div style="color:#b8903f;font-size:1.2rem;">›</div>
    </div>`;
  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 22px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">
        <button onclick="switchToTab('dashboard')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;color:#3a2a15;">📘 YKS Nedir?</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">Sınav sistemini ve puanını keşfet</div>
        </div>
      </div>
      ${kart('❓','YKS Nedir?','Oturumlar, puan türleri ve sınav sistemi','yksBilgi')}
      ${kart('📊','Soru Dağılımları','TYT ve AYT testlerinin soru sayıları','soruDagilimlari')}
      ${kart('📈','Yıllara Göre Soru Dağılımı','Konu bazında yıllara göre çıkan soru sayıları','yillaraGoreSoruDagilimi')}
      ${kart('🧮','YKS Puan Hesaplama','Netlerini gir, yaklaşık puanını gör','puanHesaplama')}
    </div>
  </div>`;
}

// ============================================================
//  ❓ YKS NEDİR? (Bilgi Ekranı)
// ============================================================
function renderYksBilgi(el) {
  const baslik = (t) => `<div style="font-weight:800;font-size:0.95rem;margin:18px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#d4af5a,#8a6a2f);border-radius:2px;"></span>${t}</div>`;
  const kutu = (icon, ad, sure, soru, aciklama) => `
    <div style="background:rgba(255,253,247,0.75);border:1px solid rgba(180,140,60,0.25);border-radius:14px;padding:12px 14px;margin-bottom:10px;">
      <div style="display:flex;align-items:center;justify-content:space-between;">
        <div style="font-weight:800;font-size:0.88rem;color:#3a2a15;">${icon} ${ad}</div>
        <div style="font-size:0.72rem;color:#8a6a2f;font-weight:700;">${soru} soru · ${sure}</div>
      </div>
      <div style="font-size:0.78rem;color:#6b5636;margin-top:6px;line-height:1.5;">${aciklama}</div>
    </div>`;
  const puanTuru = (ad, testler, renk) => `
    <div style="display:flex;align-items:center;gap:10px;background:rgba(255,253,247,0.75);border:1px solid rgba(180,140,60,0.25);border-radius:12px;padding:10px 12px;margin-bottom:8px;">
      <div style="flex-shrink:0;width:44px;height:44px;border-radius:10px;background:${renk};display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff;font-size:0.72rem;">${ad}</div>
      <div style="font-size:0.78rem;color:#3a2a15;line-height:1.4;">${testler}</div>
    </div>`;
  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 26px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">
        <button onclick="switchToTab('yksNedir')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;color:#3a2a15;">❓ YKS Nedir?</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">Yükseköğretim Kurumları Sınavı</div>
        </div>
      </div>

      <div style="font-size:0.82rem;color:#4a3a20;line-height:1.6;margin-top:10px;background:rgba(255,253,247,0.6);border-radius:12px;padding:12px 14px;border:1px solid rgba(180,140,60,0.2);">
        YKS (Yükseköğretim Kurumları Sınavı), ÖSYM tarafından her yıl düzenlenen ve üniversitelere geçişi belirleyen merkezi sınavdır. Sınav <strong>3 oturumdan</strong> oluşur: <strong>TYT</strong>, <strong>AYT</strong> ve <strong>YDT</strong>. TYT tüm adaylar için zorunludur; AYT ve YDT ise hedeflenen puan türüne göre girilir.
      </div>

      ${baslik('📋 Oturumlar')}
      ${kutu('1️⃣','TYT — Temel Yeterlilik Testi','165 dk','120','Türkçe, Matematik, Sosyal Bilimler ve Fen Bilimleri testlerinden oluşur. 9. ve 10. sınıf konularını kapsar. Ön lisans/açık öğretim programları TYT puanıyla, lisans programları için ise AYT ile birlikte kullanılır.')}
      ${kutu('2️⃣','AYT — Alan Yeterlilik Testi','180 dk','160','Matematik, Fen Bilimleri, Türk Dili ve Edebiyatı-Sosyal Bilimler-1 ve Sosyal Bilimler-2 testlerini içeren tek kitapçıktır. Aday, hedeflediği puan türüne göre bu testlerden ikisini çözer (80 soru). 11. ve 12. sınıf konularını kapsar.')}
      ${kutu('3️⃣','YDT — Yabancı Dil Testi','120 dk','80','İngilizce, Almanca, Fransızca, Arapça veya Rusça dillerinden biri seçilerek girilir. Yalnızca DİL puanı hesaplatmak isteyen adaylar için gereklidir.')}

      ${baslik('🎯 Puan Türleri ve Sorumlu Olunan Testler')}
      ${puanTuru('SAY','<strong>Sayısal:</strong> TYT + AYT Matematik + AYT Fen Bilimleri','linear-gradient(135deg,#1d4ed8,#3b82f6)')}
      ${puanTuru('EA','<strong>Eşit Ağırlık:</strong> TYT + AYT Matematik + AYT Türk Dili ve Edebiyatı-Sosyal Bilimler-1','linear-gradient(135deg,#9333ea,#a855f7)')}
      ${puanTuru('SÖZ','<strong>Sözel:</strong> TYT + AYT Türk Dili ve Edebiyatı-Sosyal Bilimler-1 + AYT Sosyal Bilimler-2','linear-gradient(135deg,#dc2626,#f87171)')}
      ${puanTuru('DİL','<strong>Dil:</strong> TYT + YDT (Yabancı Dil Testi)','linear-gradient(135deg,#16a34a,#4ade80)')}

      <div style="font-size:0.68rem;color:#8a7a5c;margin-top:14px;line-height:1.5;">⚠️ Sınav içerikleri ve süreler ÖSYM tarafından yıldan yıla güncellenebilir; en güncel ve resmi bilgi için ÖSYM'nin yayımladığı YKS kılavuzunu kontrol etmeni öneririz.</div>
    </div>
  </div>`;
}

// ============================================================
//  📊 SORU DAĞILIMLARI
// ============================================================
function renderSoruDagilimlari(el) {
  const barSatir = (ad, soru, toplam, renk) => {
    const pct = Math.round(soru / toplam * 100);
    return `
    <div style="margin-bottom:10px;">
      <div style="display:flex;justify-content:space-between;font-size:0.78rem;color:#3a2a15;margin-bottom:3px;">
        <span style="font-weight:700;">${ad}</span>
        <span style="font-weight:800;color:#8a6a2f;">${soru} soru</span>
      </div>
      <div style="height:9px;background:rgba(180,140,60,0.15);border-radius:6px;overflow:hidden;">
        <div style="height:100%;width:${pct}%;background:${renk};border-radius:6px;"></div>
      </div>
    </div>`;
  };
  const testKart = (baslik2, toplamSoru, sure, satirlar) => `
    <div style="background:rgba(255,253,247,0.75);border:1px solid rgba(180,140,60,0.25);border-radius:14px;padding:14px 14px 10px;margin-bottom:14px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
        <div style="font-weight:800;font-size:0.88rem;color:#3a2a15;">${baslik2}</div>
        <div style="font-size:0.7rem;color:#6b5636;font-weight:700;">${toplamSoru} soru · ${sure}</div>
      </div>
      ${satirlar}
    </div>`;

  el.innerHTML = `
  <div class="fade-up" style="max-width:560px;margin:0 auto;">
    <div style="position:relative;border-radius:22px;overflow:hidden;padding:18px 16px 26px;background:radial-gradient(circle at 20% 10%,rgba(212,169,80,0.18),transparent 45%),linear-gradient(160deg,#faf6ec,#f0e8d4 60%,#ece2c8);border:1px solid rgba(180,140,60,0.3);box-shadow:0 8px 22px rgba(120,90,30,0.15);">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">
        <button onclick="switchToTab('yksNedir')" style="background:none;border:none;cursor:pointer;padding:0;display:flex;flex-shrink:0;"><img src="${GERI_TUS_ICON}" style="width:32px;height:32px;"></button>
        <div>
          <div style="font-family:'Playfair Display',serif;font-size:1.4rem;font-weight:900;color:#3a2a15;">📊 Soru Dağılımları</div>
          <div style="font-size:0.8rem;color:#6b5636;margin-top:2px;">TYT ve AYT testlerinin soru sayıları</div>
        </div>
      </div>

      <div style="font-weight:800;font-size:0.9rem;margin:16px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#5a9ee8,#1d4ed8);border-radius:2px;"></span>TYT — 120 Soru</div>
      ${testKart('Türkçe Testi', 40, '', barSatir('Türkçe', 40, 40, 'linear-gradient(90deg,#b45309,#f59e0b)'))}
      ${testKart('Sosyal Bilimler Testi', 20, '', barSatir('Tarih', 5, 20, 'linear-gradient(90deg,#78350f,#b45309)') + barSatir('Coğrafya', 5, 20, 'linear-gradient(90deg,#065f46,#10b981)') + barSatir('Felsefe', 5, 20, 'linear-gradient(90deg,#581c87,#9333ea)') + barSatir('Din Kültürü', 5, 20, 'linear-gradient(90deg,#78350f,#ca8a04)'))}
      ${testKart('Temel Matematik Testi', 40, '', barSatir('Matematik (Geometri dahil)', 40, 40, 'linear-gradient(90deg,#1d4ed8,#3b82f6)'))}
      ${testKart('Fen Bilimleri Testi', 20, '', barSatir('Fizik', 7, 20, 'linear-gradient(90deg,#0c4a6e,#0284c7)') + barSatir('Kimya', 7, 20, 'linear-gradient(90deg,#4c1d95,#9333ea)') + barSatir('Biyoloji', 6, 20, 'linear-gradient(90deg,#14532d,#16a34a)'))}
      <div style="font-size:0.72rem;color:#6b5636;margin:2px 0 6px;">⏱️ Toplam süre: 165 dakika</div>

      <div style="font-weight:800;font-size:0.9rem;margin:18px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#dc2626,#7f1d1d);border-radius:2px;"></span>AYT — 160 Soru (Kitapçık)</div>
      ${testKart('Matematik Testi', 40, '', barSatir('Matematik (Geometri dahil)', 40, 40, 'linear-gradient(90deg,#1d4ed8,#3b82f6)'))}
      ${testKart('Fen Bilimleri Testi', 40, '', barSatir('Fizik', 14, 40, 'linear-gradient(90deg,#0c4a6e,#0284c7)') + barSatir('Kimya', 13, 40, 'linear-gradient(90deg,#4c1d95,#9333ea)') + barSatir('Biyoloji', 13, 40, 'linear-gradient(90deg,#14532d,#16a34a)'))}
      ${testKart('Türk Dili ve Edebiyatı-Sosyal Bilimler-1', 40, '', barSatir('Türk Dili ve Edebiyatı', 24, 40, 'linear-gradient(90deg,#7f1d1d,#dc2626)') + barSatir('Tarih-1', 10, 40, 'linear-gradient(90deg,#78350f,#b45309)') + barSatir('Coğrafya-1', 6, 40, 'linear-gradient(90deg,#065f46,#059669)'))}
      ${testKart('Sosyal Bilimler-2 Testi', 40, '', barSatir('Tarih-2', 11, 40, 'linear-gradient(90deg,#78350f,#b45309)') + barSatir('Coğrafya-2', 11, 40, 'linear-gradient(90deg,#065f46,#059669)') + barSatir('Felsefe Grubu (Felsefe/Psikoloji/Sosyoloji/Mantık)', 12, 40, 'linear-gradient(90deg,#581c87,#9333ea)') + barSatir('Din Kültürü', 6, 40, 'linear-gradient(90deg,#78350f,#ca8a04)'))}
      <div style="font-size:0.72rem;color:#6b5636;margin:2px 0 6px;">⏱️ Toplam süre: 180 dakika · Her aday, hedeflediği puan türüne göre bu testlerden yalnızca 2'sini (80 soru) çözer.</div>

      <div style="font-weight:800;font-size:0.9rem;margin:18px 0 8px;color:#3a2a15;display:flex;align-items:center;gap:8px;"><span style="width:4px;height:16px;background:linear-gradient(180deg,#16a34a,#14532d);border-radius:2px;"></span>YDT — 80 Soru</div>
      ${testKart('Yabancı Dil Testi', 80, '120 dk', barSatir('İngilizce / Almanca / Fransızca / Arapça / Rusça', 80, 80, 'linear-gradient(90deg,#14532d,#16a34a)'))}

      <div style="font-size:0.68rem;color:#8a7a5c;margin-top:10px;line-height:1.5;">⚠️ Soru sayıları ÖSYM'nin YKS kılavuzuna göre verilmiştir; yıldan yıla küçük değişiklikler olabilir. Güncel bilgi için ÖSYM duyurularını takip et.</div>
    </div>
  </div>`;
}

// ============================================================
//  📈 YILLARA GÖRE SORU DAĞILIMI (Soru Bankasından Tespit)
// ============================================================
let yilDagilimUI = { ders: null };

// Bu ekranda dersler bazı testlerin gerçek soru kâğıdı gruplamasına göre
// aynı renkte gösterilir (aynı test içindeki dersler aynı arka plan rengini paylaşır).
const YIL_DAGILIM_TYT_GRUPLAR = [
  { grad:'linear-gradient(135deg,#b45309,#f59e0b)', anahtarlar:['tytTurkce'] },
  { grad:'linear-gradient(135deg,#1d4ed8,#3b82f6)', anahtarlar:['tytMatematik','tytGeometri'] },
  { grad:'linear-gradient(135deg,#9d174d,#ec4899)', anahtarlar:['tytTarih','tytCografya','tytFelsefe','tytDin'] },
  { grad:'linear-gradient(135deg,#065f46,#10b981)', anahtarlar:['tytFizik','tytKimya','tytBiyoloji'] },
];
const YIL_DAGILIM_AYT_GRUPLAR = [
  { grad:'linear-gradient(135deg,#7f1d1d,#dc2626)', anahtarlar:['aytEdebiyat','aytTarih1','aytCografya1'] },
  { grad:'linear-gradient(135deg,#1d4ed8,#3b82f6)', anahtarlar:['aytMatematik','aytGeometri'] },
  { grad:'linear-gradient(135deg,#78350f,#b45309)', anahtarlar:['aytTarih2','aytCografya2','aytFelsefe','aytPsikoloji','aytSosyoloji','aytMantik','aytDin'] },
  { grad:'linear-gradient(135deg,#0c4a6e,#0284c7)', anahtarlar:['aytFizik','aytKimya','aytBiyoloji'] },
];

function yilDagilimSecDers(dersKey) {
  yilDagilimUI.ders = dersKey;
  renderYillaraGoreSoruDagilimi(document.getElementById('mainContent'));
}
function yilDagilimGeriListe() {
  yilDagilimUI.ders = null;
  renderYillaraGoreSoruDagilimi(document.getElementById('mainContent'));
}
// Tarih-1 / Tarih-2, Veri Girişi / Soru Bankası / Konu İzle ekranlarında tek bir
// "Tarih" dersi olarak birleştirildi (bkz. VG_DERSLER.AYT — key:'aytTarih').
// Yıllara Göre Soru Dağılımı ekranı ise gerçek sınav kitapçığı ayrımını (Tarih-1 / Tarih-2)
// korumak zorunda olduğundan, bu iki dersin ORİJİNAL tanımları burada saklanır ve
// yilDagilimDersBilgi() bu ekran için VG_DERSLER'dan bağımsız olarak bunları kullanır.
const YIL_DAGILIM_LEGACY_DERS_BILGI = {
  aytCografya1: { key:'aytCografya1', ad:'Coğrafya-1',  emoji:'🗺️', renk:'#059669', grad:'linear-gradient(135deg,#065f46,#059669)', kazanimlar:['Doğal Sistemler','Beşerî Sistemler','Küresel Ortam: Bölgeler ve Ülkeler','Çevre ve Toplum'] },
  aytCografya2: { key:'aytCografya2', ad:'Coğrafya-2',  emoji:'🗺️', renk:'#059669', grad:'linear-gradient(135deg,#065f46,#059669)', kazanimlar:['Doğal Sistemler','Beşerî Sistemler','Küresel Ortam: Bölgeler ve Ülkeler','Çevre ve Toplum'] },
  aytTarih1: { key:'aytTarih1',    ad:'Tarih-1',     emoji:'🏛️', renk:'#b45309', grad:'linear-gradient(135deg,#78350f,#b45309)', kazanimlar:['Tarih ve Zaman','İnsanlığın İlk Dönemleri','İlk ve Orta Çağlarda Türk Dünyası','İslam Medeniyetinin Doğuşu',"Türklerin İslamiyet'i Kabulü ve İlk Türk İslam Devletleri",'Yerleşme ve Devletleşme Sürecinde Selçuklu Türkiyesi','Beylikten Devlete Osmanlı Siyaseti (1302-1453)','Devletleşme Sürecinde Savaşçılar ve Askerler','Dünya Gücü Osmanlı (1453-1595)','Sultan ve Osmanlı Merkez Teşkilatı','Değişim Çağında Avrupa ve Osmanlı','Devrimler Çağında Değişen Devlet-Toplum İlişkileri','Uluslararası İlişkilerde Denge Stratejisi (1774-1914)','XIX ve XX. Yüzyılda Değişen Sosyoekonomik Hayat','20. Yüzyıl Başlarında Osmanlı Devleti ve Dünya','Millî Mücadele','Atatürkçülük ve Türk İnkılabı','İki Savaş Arasındaki Dönemde Türkiye ve Dünya','II. Dünya Savaşı Sürecinde Türkiye ve Dünya'] },
  aytTarih2: { key:'aytTarih2',    ad:'Tarih-2',     emoji:'🏛️', renk:'#b45309', grad:'linear-gradient(135deg,#78350f,#b45309)', kazanimlar:['Tarih ve Zaman','İnsanlığın İlk Dönemleri','İlk ve Orta Çağlarda Türk Dünyası',"Türklerin İslamiyet'i Kabulü ve İlk Türk İslam Devletleri",'Yerleşme ve Devletleşme Sürecinde Selçuklu Türkiyesi','Beylikten Devlete Osmanlı Siyaseti (1302-1453)','Devletleşme Sürecinde Savaşçılar ve Askerler','Beylikten Devlete Osmanlı Medeniyeti','Dünya Gücü Osmanlı (1453-1595)','Sultan ve Osmanlı Merkez Teşkilatı',"Klasik Çağ'da Osmanlı Toplum Düzeni",'Değişen Dünya Dengeleri Karşısında Osmanlı Siyaseti (1595-1774)','Değişim Çağında Avrupa ve Osmanlı','Devrimler Çağında Değişen Devlet-Toplum İlişkileri','Uluslararası İlişkilerde Denge Stratejisi (1774-1914)','20. Yüzyıl Başlarında Osmanlı Devleti ve Dünya','Millî Mücadele','Atatürkçülük ve Türk İnkılabı','II. Dünya Savaşı Sürecinde Türkiye ve Dünya','İkinci Dünya Savaşı Sonrasında Türkiye ve Dünya','Toplumsal Devrim Çağında Dünya ve Türkiye','21. Yüzyılın Eşiğinde Türkiye ve Dünya'] }
};
function yilDagilimDersBilgi(dersKey) {
  if (YIL_DAGILIM_LEGACY_DERS_BILGI[dersKey]) return YIL_DAGILIM_LEGACY_DERS_BILGI[dersKey];
  const tyt = (VG_DERSLER.TYT || []).find(d => d.key === dersKey);
  if (tyt) return tyt;
  const ayt = (VG_DERSLER.AYT || []).find(d => d.key === dersKey);
  if (ayt) return ayt;
  const ydt = (VG_DERSLER.YDT || []).find(d => d.key === dersKey);
  if (ydt) return ydt;
  return { key: dersKey, ad: dersKey, emoji:'📘', kazanimlar: [] };
}
